"""Timing rollout checks executed only in disposable offline PostgreSQL."""
rpc('task_app_setup',"'bootstrap',null",owner)
cat=sql(f"select id from public.categories where owner_id='{owner}'and name='Healing Meeting';")
# An active old-rule absence extends; expired/cancelled history never revives.
a=sql(f"insert into public.account_member_absences(owner_id,member_id,category_id,created_at,expires_at)values('{owner}','{mm}','{cat}',now(),((now()at time zone 'Asia/Kolkata')::date+7+time '23:50')at time zone 'Asia/Kolkata')returning id;")
old_end=sql(f"select expires_at from public.account_member_absences where id='{a}';")
expired=sql(f"insert into public.account_member_absences(owner_id,member_id,category_id,created_at,expires_at)values('{owner}','{cm}','{cat}',now()-interval '2 days',((now()at time zone 'Asia/Kolkata')::date-1+time '23:50')at time zone 'Asia/Kolkata')returning id;")
expired_row=sql(f"select to_jsonb(a)from public.account_member_absences a where id='{expired}';")
# Populate candidates through real task triggers, not client-authored candidate writes.
sql("update public.task_fine_configuration set enabled_at=now()-interval '30 days';")
special=sql(f"select id from public.categories where owner_id='{owner}'and name='Special Meeting';")
task_id=sql(f"insert into public.tasks(owner_id,title,status,priority,category_id,assigned_to_member_id,due_date,due_time)values('{owner}','Future fine timing','active','medium','{special}','{mm}',(now()at time zone 'Asia/Kolkata')::date+8,'23:50')returning id;")
sql(f"insert into public.task_fines(owner_id,task_id,title,category_name,member_id,member_name,cutoff_at)values('{owner}','00000000-0000-4000-8000-000000009990','Issued historical fine','Healing Meeting','{mm}','Sarah',now()-interval '3 days');")
fine_before=sql('select to_jsonb(f)from public.task_fines f;')
activation=sql('select enabled_at from public.task_fine_configuration;')
grants=sql("select jsonb_object_agg(proname,coalesce(proacl::text,''))from pg_proc where pronamespace='public'::regnamespace and proname in('task_app_history_expires','task_app_mark_absent','task_app_fine_cutoff','task_app_member_history');")
sql((root/'supabase/migrations/202610150022_exact_meeting_windows.sql').read_text())
check('active absence includes final minute until exclusive midnight',sql(f"select expires_at='{old_end}'::timestamptz+interval '10 minutes'from public.account_member_absences where id='{a}';")=='t')
check('expired absence history unchanged',sql(f"select to_jsonb(a)from public.account_member_absences a where id='{expired}';")==expired_row)
check('issued fine and prospective activation unchanged',sql('select to_jsonb(f)from public.task_fines f;')==fine_before and sql('select enabled_at from public.task_fine_configuration;')==activation)
check('future candidate changes to following-day01 without issuing a charge',sql(f"select cutoff_at=((scheduled_date+1)+time '01:00')at time zone 'Asia/Kolkata'and not finalized from public.task_fine_candidates where task_id='{task_id}';")=='t'and sql('select count(*)from public.task_fines;')=='1')
check('existing function access preserved',sql("select jsonb_object_agg(proname,coalesce(proacl::text,''))from pg_proc where pronamespace='public'::regnamespace and proname in('task_app_history_expires','task_app_mark_absent','task_app_fine_cutoff','task_app_member_history');")==grants)
for name,start,end in [('Sunday Service','2026-10-18','2026-10-19'),('Healing Meeting','2026-10-21','2026-10-22'),('Revival Meeting','2026-10-23','2026-10-24'),('Special Meeting','2026-10-24','2026-10-25')]:
 check(name+' following-day01 fine',sql(f"select public.task_app_fine_cutoff('{name}','{start}','23:50')='{end}T01:00:00+05:30'::timestamptz;")=='t')
 check(name+' history includes last second of11:59',sql(f"select public.task_app_history_expires('{name}','{start}T12:00:00+05:30','{start}','{{}}')=('{end}'::date+1)::timestamp at time zone 'Asia/Kolkata';")=='t')
 check(name+' end is later than last millisecond',sql(f"select public.task_app_history_expires('{name}','{start}T12:00:00+05:30','{start}','{{}}')>'{end}T23:59:59.999+05:30'::timestamptz;")=='t')
check('date-only task due after01 stays protected from early fine',sql("select public.task_app_fine_cutoff('Sunday Service','2026-10-19',null)='2026-10-26T01:00:00+05:30'::timestamptz;")=='t')
check('late Sunday completion gets next period, not immediate expiry',sql("select public.task_app_history_expires('Sunday Service','2026-10-20T00:00:00+05:30',null,'{}')='2026-10-27T00:00:00+05:30'::timestamptz;")=='t')
check('Special year rollover follows the same two-day window',sql("select public.task_app_history_expires('Special Meeting','2026-12-31T12:00:00+05:30','2026-12-31','{}')='2027-01-02T00:00:00+05:30'::timestamptz;")=='t')
for who in [None,owner,member]:
 if who is not None:check('authorized history read retains workspace members',len(rpc('task_app_member_history','',who)['members'])==3)
expect('anonymous history RPC remains private','set role anon;select public.task_app_member_history();',None,'42501')
sql((root/'supabase/migrations/202610150022_exact_meeting_windows.sql').read_text(),fail='already installed')
verification=sql((root/'supabase/verification/20261015_exact_meeting_windows_checks.sql').read_text())
check('read-only timing and access verification all zero',all(line.rsplit('|',1)[1]=='0'for line in verification.splitlines()))
print('Exact meeting windows SQL integration passed.',flush=True)
